func:
let entorno = global.get("ruta_actual") || "simulacion";
let tema = msg.topic;

// 1. 🔥 FIREWALL ANTI-BUCLES (Bloquea los "Ecos" de la interfaz)
// Si la pantalla intentó reenviar telemetría o estados, los destruimos aquí.
if (tema.startsWith("sensor/") || 
    tema === "panel/selector" || 
    tema.includes("/estado") || 
    tema.startsWith("panel/led/")) {
    return null; // Retornar 'null' mata el mensaje. Fin de la tormenta.
}

// Estandarizamos booleanos a Strings ("1" o "0")
if (msg.payload === true) msg.payload = "1";
if (msg.payload === false) msg.payload = "0";

// 2. ENRUTAMIENTO DE ÓRDENES PURAS
if (entorno === "simulacion") {
    // Si estamos en Gemelo Digital, añadimos el prefijo para Webots
    msg.topic = "maquina/simulacion/" + tema.replace("actuador/", "");
} else {
    // Si estamos en Físico, enviamos la orden directa al ESP32
    msg.topic = tema;
}

return msg;
